            aIngress ^= (RotL64(aFireLaneC[((aIndex + 8200U)) & S_BLOCK1], 51U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 11220U)) & S_BLOCK1], 29U));
