            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 12162U)) & S_BLOCK1], 37U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 8294U)) & S_BLOCK1], 11U));
