            aScatter = (RotL64(aCross, 37U) ^ RotL64(aPrevious, 3U)) + (RotL64(aCarry, 21U) + RotL64(aIngress, 50U));
            aScatter = TwistMix64::DiffuseB(((aScatter ^ aPhaseBDomainWordScatter) ^ aNonceWordF));
            //
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 5U)) + RotL64(aCarry, 37U)) + 0x2EF0C7DA7DA026BBULL;
            aOrbiterI = ((aWandererD + RotL64(aCross, 13U)) + 0xEB964B7A1D3C4EB8ULL) + aPhaseBOrbiterAssignSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterG = (((aWandererI + RotL64(aIngress, 44U)) + RotL64(aCarry, 57U)) + 0x5C3ACDAD1C283C77ULL) + aNonceWordO;
            aOrbiterD = ((aWandererG + RotL64(aScatter, 39U)) + RotL64(aCarry, 27U)) + 0xA22741C7BB9DF99BULL;
            aOrbiterK = (aWandererK + RotL64(aIngress, 19U)) + 0x9432ECBDEE41DB92ULL;
            aOrbiterJ = (aWandererC + RotL64(aPrevious, 11U)) + 0xDA1D6D63ADCB3C4DULL;
            aOrbiterF = ((aWandererH + RotL64(aScatter, 3U)) + 0x56D4C8206EEFA227ULL) + aNonceWordC;
            aOrbiterH = (aWandererF + RotL64(aCross, 57U)) + 0x844F623F95EE17D2ULL;
            aOrbiterB = ((aWandererJ + RotL64(aIngress, 24U)) + 0xD91E30E72DEBF59EULL) + aNonceWordI;
            aOrbiterE = (((aWandererE + RotL64(aCross, 21U)) + 0x82CD1A57BA44B8E3ULL) + aPhaseBOrbiterAssignSaltB[(((31U - aIndex) + 24U)) & S_SALT1]) + aNonceWordF;
            aOrbiterA = (aWandererA + RotL64(aPrevious, 27U)) + 0xBCA5BA27A0256A3AULL;
