            aWandererG = aWandererG ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterK, 5U)) + aOrbiterJ);
            aWandererE = aWandererE + ((((RotL64(aScatter, 44U) + aOrbiterH) + RotL64(aOrbiterK, 35U)) + aNonceWordP) + aPhaseBWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aIngress, 11U) + aOrbiterK) + RotL64(aOrbiterI, 19U)) + aNonceWordJ);
            //
            aCarry = aCarry + (RotL64(aWandererB, 39U) ^ aWandererF);
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererG, 24U));
            aCarry = aCarry + (RotL64(aWandererJ, 47U) ^ aWandererC);
            aCarry = aCarry + (RotL64(aWandererI, 35U) ^ aWandererE);
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererK, 43U));
