            aWandererK = aWandererK + ((((RotL64(aIngress, 60U) + RotL64(aOrbiterK, 35U)) + aOrbiterE) + RotL64(aCarry, 57U)) + aPhaseBWandererUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1]);
