            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x6CB2C0493822B65BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x2D2F3C412FC5D8C7ULL;
