            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 7177U)) & S_BLOCK1], 50U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 5465U)) & S_BLOCK1], 3U));
