            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 23U) ^ RotL64(aCross, 57U)) ^ (RotL64(aCarry, 5U) + RotL64(aPrevious, 44U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = ((aWandererF + RotL64(aIngress, 13U)) + RotL64(aCarry, 29U)) + 0x03C9259D98987D1EULL;
            aOrbiterE = (((aWandererH + RotL64(aPrevious, 37U)) + RotL64(aCarry, 3U)) + 0x2C62BAEE50CDCA47ULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterI = ((aWandererJ + RotL64(aCross, 29U)) + 0x9E58327C14A8BF90ULL) + aPhaseBOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterF = (aWandererB + RotL64(aScatter, 57U)) + 0x2BAA713BBEAE9EC1ULL;
            aOrbiterC = (aWandererG + RotL64(aCross, 5U)) + 0x9290ECC05A70CD8AULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 22U)) + RotL64(aCarry, 53U)) + 0x21381EB795BA1D63ULL;
            aOrbiterG = (aWandererA + RotL64(aIngress, 51U)) + 0x67ED34A7AC478253ULL;
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0xFA6A353C46345906ULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x9F861E05D92B4D21ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xF81B9FB87C0B4949ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x2A09A69BA22A2838ULL;
