            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x0A7667489CE3C085ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xD5F84149F5F796FCULL;
            aOrbiterG = RotL64((aOrbiterG * 0xE7BCB4BAB69A4D2BULL), 51U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0xE325A905A56407B7ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x6914885CBDBBD996ULL) ^ aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x31889E4A96024715ULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x7EC2AA2C5D5B5546ULL;
