            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x5E51F82AB1103BEEULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x84B359032876D4ADULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8ABAAD572E421CBDULL), 13U);
